<?php

declare(strict_types = 1);

namespace SineMacula\Laravel\Sso\Keys\Enums;

use SineMacula\Laravel\Sso\Freshness\Enums\FreshnessOperation;

/**
 * What a row of the keys and certificates table is for (SSO-2.6, SSO-2.7,
 * SSO-2.8): one of the service provider's own key pairs, generated by the
 * package with a self-signed certificate and rotated through `next`, `current`
 * and `retiring`; a signing certificate of the identity provider that the
 * connection trusts, one of a set; or a certificate the identity provider's
 * metadata must be signed by, one of the connection's metadata signing anchor
 * set.
 *
 * Backed, and stable once released: a value is never renamed or reused.
 *
 * @api
 *
 * @author      Ben Carey <bdmc@sinemacula.co.uk>
 * @copyright   2026 Sine Macula Limited
 */
enum KeyUse: string
{
    // The SAML service provider's signing key pair: `AuthnRequest` signatures
    // (SSO-2.7, SSO-5.3)
    case SP_SIGNING = 'sp_signing';

    // The SAML service provider's encryption key pair: encrypted assertions are
    // decrypted with it (SSO-2.7, SSO-6.8)
    case SP_ENCRYPTION = 'sp_encryption';

    // The OIDC relying party's `private_key_jwt` key pair: client assertions
    // are signed with it (SSO-2.4, RFC 7523)
    case CLIENT_ASSERTION = 'client_assertion';

    // A signing certificate of the identity provider that the connection
    // trusts, one of a set (SSO-2.6)
    case IDP_SIGNING = 'idp_signing';

    // A certificate the identity provider's metadata must be signed by, one of
    // the connection's metadata signing anchor set (SSO-2.8)
    case METADATA_SIGNING = 'metadata_signing';

    /**
     * Whether the row is one of the service provider's own key pairs, with an
     * encrypted private key and a state, rather than a trusted certificate.
     *
     * @return bool
     */
    public function isOwnKey(): bool
    {
        return !$this->isTrustedCertificate();
    }

    /**
     * Whether the row is a certificate the connection trusts, an identity
     * provider signing certificate or a metadata signing anchor, with no
     * private key and no state.
     *
     * @return bool
     */
    public function isTrustedCertificate(): bool
    {
        return $this === self::IDP_SIGNING || $this === self::METADATA_SIGNING;
    }

    /**
     * The protocol the use belongs to.
     *
     * @return string
     */
    public function protocol(): string
    {
        return $this === self::CLIENT_ASSERTION ? 'oidc' : 'saml2';
    }

    /**
     * The key types a row of this use may hold: RSA only for SAML, whose
     * library signs and verifies RSA alone and whose key transport is RSA-OAEP
     * (SSO-6.7, `docs/design/saml-library.md`), and RSA or elliptic curve for
     * an OIDC client assertion key.
     *
     * @return list<\SineMacula\Laravel\Sso\Keys\Enums\KeyType>
     */
    public function allowedTypes(): array
    {
        return $this === self::CLIENT_ASSERTION ? [KeyType::RSA, KeyType::EC] : [KeyType::RSA];
    }

    /**
     * The operation whose freshness a change to a row of this use needs: a
     * trusted certificate or metadata signing anchor is trust
     * (`sso.connection.trust`), a key of the service provider's own is rotation
     * (`sso.keys.rotate`) (SSO-2.12).
     *
     * @return \SineMacula\Laravel\Sso\Freshness\Enums\FreshnessOperation
     */
    public function freshness(): FreshnessOperation
    {
        return $this->isOwnKey() ? FreshnessOperation::KEYS_ROTATE : FreshnessOperation::CONNECTION_TRUST;
    }
}
